import json
import logging
import os
from collections.abc import AsyncIterator

from fastapi import FastAPI, Request
from fastapi.responses import FileResponse, JSONResponse, StreamingResponse
from openai import AsyncOpenAI
from starlette.middleware.cors import CORSMiddleware


logger = logging.getLogger("chat")
logging.basicConfig(level=logging.INFO)


app = FastAPI()
app.add_middleware(
    CORSMiddleware,
    allow_origins=["*"],
    allow_credentials=False,
    allow_methods=["GET", "POST", "OPTIONS"],
    allow_headers=["*"],
)


def client() -> AsyncOpenAI:
    api_key = os.getenv("BLUESMINDS_API_KEY") or os.getenv("OPENAI_API_KEY")
    if not api_key:
        raise RuntimeError("BLUESMINDS_API_KEY nincs beállítva.")
    return AsyncOpenAI(
        api_key=api_key,
        base_url=os.getenv("BLUESMINDS_BASE_URL", ""),
    )


def make_messages(payload: dict) -> list[dict]:
    messages = payload.get("messages")
    if isinstance(messages, list) and messages:
        result = []
        for item in messages:
            if not isinstance(item, dict):
                continue
            role = item.get("role")
            content = item.get("content")
            if role not in {"system", "user", "assistant"}:
                continue
            if isinstance(content, str) and content.strip():
                result.append({"role": role, "content": content})
            elif isinstance(content, list):
                text_parts = []
                for part in content:
                    if not isinstance(part, dict):
                        continue
                    if part.get("type") == "text" and isinstance(part.get("text"), str):
                        text_parts.append(part["text"])
                content_text = "\n".join(text_parts).strip()
                if content_text:
                    result.append({"role": role, "content": content_text})
        if result:
            return result

    text = payload.get("fullText") or payload.get("rawText") or payload.get("message")
    if not isinstance(text, str) or not text.strip():
        raise ValueError("Az üzenet üres.")
    return [{"role": "user", "content": text}]


def sse(event: str, data: dict) -> str:
    return f"event: {event}\ndata: {json.dumps(data, ensure_ascii=False)}\n\n"


async def stream_completion(payload: dict) -> AsyncIterator[str]:
    try:
        messages = make_messages(payload)
        model = os.getenv("BLUESMINDS_MODEL", "claude-fable-5")
        logger.info("chat_completion model=%s message_count=%d", model, len(messages))
        response = await client().chat.completions.create(
            model=model,
            messages=messages,
        )
        choices = getattr(response, "choices", None) or []
        if not choices:
            raise RuntimeError("A modell üres választ adott.")
        message = getattr(choices[0], "message", None)
        text = getattr(message, "content", None) if message else None
        if not isinstance(text, str) or not text:
            raise RuntimeError("A modell nem adott szöveges választ.")
        logger.info("chat_completion_success model=%s response_length=%d", model, len(text))
        yield sse("content", {"delta": text})
        yield sse("done", {"done": True})
    except ValueError as error:
        logger.error("chat_completion_request_error error=%s", error)
        yield sse("error", {"message": str(error), "type": "request_error"})
    except Exception as error:
        logger.error("chat_completion_provider_error model=%s error=%s", model if "model" in locals() else "unknown", error)
        yield sse("error", {"message": str(error), "type": "provider_error"})


@app.get("/")
async def index() -> FileResponse:
    return FileResponse("index.html", media_type="text/html")


@app.get("/manifest.webmanifest")
async def manifest() -> FileResponse:
    return FileResponse("manifest.webmanifest", media_type="application/manifest+json")


@app.get("/sw.js")
async def service_worker() -> FileResponse:
    return FileResponse("sw.js", media_type="application/javascript")


@app.get("/health")
async def health() -> JSONResponse:
    configured = bool(os.getenv("BLUESMINDS_API_KEY") or os.getenv("OPENAI_API_KEY"))
    return JSONResponse({"ok": True, "provider_configured": configured})


@app.post("/api/chat", response_model=None)
async def chat(request: Request):
    try:
        payload = await request.json()
    except Exception:
        return JSONResponse({"message": "Érvénytelen JSON kérés."}, status_code=400)
    if not isinstance(payload, dict):
        return JSONResponse({"message": "A kérés törzsének objektumnak kell lennie."}, status_code=400)
    if not (os.getenv("BLUESMINDS_API_KEY") or os.getenv("OPENAI_API_KEY")):
        return JSONResponse({"message": "BLUESMINDS_API_KEY nincs beállítva."}, status_code=503)
    return StreamingResponse(
        stream_completion(payload),
        media_type="text/event-stream",
        headers={
            "Cache-Control": "no-cache, no-transform",
            "Connection": "keep-alive",
            "X-Accel-Buffering": "no",
        },
    )


if __name__ == "__main__":
    import uvicorn

    uvicorn.run("main:app", host="0.0.0.0", port=int(os.getenv("PORT", "5000")))

